import type { Level, Question, Subject, Track } from './types';

// All question files are bundled, so the app works offline. Files are generated by
// scripts/build-bank.mjs (which validates every question) from scripts/src/*.mjs.
const files = import.meta.glob<{ default: Question[] }>('../data/bank/*.json', { eager: true });

export const BANK: Question[] = Object.values(files).flatMap((m) => m.default);
export const BY_ID: Record<string, Question> = Object.fromEntries(BANK.map((q) => [q.id, q]));

export const topicsOf = (s?: Subject) => [...new Set(BANK.filter((q) => !s || q.subject === s).map((q) => q.topic))].sort();

export interface Filter {
  subjects?: Subject[];
  topics?: string[];
  levels?: Level[];
  tracks?: Track[];
  iq?: boolean;
  maxTime?: number;
}

export function filterBank(f: Filter): Question[] {
  return BANK.filter(
    (q) =>
      (!f.subjects?.length || f.subjects.includes(q.subject)) &&
      (!f.topics?.length || f.topics.includes(q.topic)) &&
      (!f.levels?.length || f.levels.includes(q.level)) &&
      (!f.tracks?.length || q.tracks.some((t) => f.tracks!.includes(t))) &&
      (f.iq === undefined || q.iq === f.iq) &&
      (!f.maxTime || q.time <= f.maxTime),
  );
}

export const topicKey = (q: Pick<Question, 'subject' | 'topic'>) => `${q.subject}::${q.topic}`;
